Record Product
  Define name As String;
  Define price, stock As Integer;
EndRecord

Function amount <- LineAmount(price As Integer, quantity As Integer)
  Define amount As Integer;
  amount <- price * quantity;
EndFunction

Function discounted <- WithDiscount(total As Integer)
  Define discounted As Integer;
  discounted <- total - total Div 10;
EndFunction

Function isValid <- IsValidCode(code As Integer)
  Define isValid As Boolean;
  isValid <- code >= 1 And code <= 5;
EndFunction

Subroutine Catalog() As Vector<Product>
  Define products As Vector<Product> <- vector();
  products.append(Product("Juice", 3, 10));
  products.append(Product("Sandwich", 5, 5));
  products.append(Product("Alfajor", 2, 8));
  products.append(Product("Water", 1, 12));
  products.append(Product("Fruit", 2, 6));
  Return products;
EndSubroutine

Algorithm Kiosk
  Define products As Vector<Product> <- Catalog();
  Define total As Integer <- 0;
  Define code, quantity As Integer;
  Read code;
  While code <> 0 Do
    Read quantity;
    If Not IsValidCode(code) Then
      Write "Code ", code, " does not exist";
    Else
      If quantity < 1 Then
        Write "Quantity ", quantity, " is not valid";
      Else
        Define product As Product <- products[code - 1];
        If quantity > product.stock Then
          Write product.name, " x ", quantity, " rejected: stock is ", product.stock;
        Else
          product.stock <- product.stock - quantity;
          products[code - 1] <- product;
          Write product.name, " x ", quantity, " = ", LineAmount(product.price, quantity);
          total <- total + LineAmount(product.price, quantity);
        EndIf
      EndIf
    EndIf
    Read code;
  EndWhile
  Write "Total: ", total;
  Write "With discount: ", WithDiscount(total);
  Write "Final stock:";
  For Each product In products Do
    Write product.name, " ", product.stock;
  EndFor
EndAlgorithm
